import{_ as e,c as t,o,a4 as r}from"./chunks/framework.BYxathSa.js";const h=JSON.parse('{"title":"Q6：React 类组件生命周期详解","description":"","frontmatter":{},"headers":[],"relativePath":"react/q6.md","filePath":"react/q6.md","lastUpdated":null}'),c={name:"react/q6.md"},a=r('<h1 id="q6-react-类组件生命周期详解" tabindex="-1">Q6：React 类组件生命周期详解 <a class="header-anchor" href="#q6-react-类组件生命周期详解" aria-label="Permalink to &quot;Q6：React 类组件生命周期详解&quot;">​</a></h1><p>生命周期分为三个阶段：</p><p><strong>挂载阶段</strong></p><ol><li><code>constructor(props)</code>：初始化 state，绑定方法。</li><li><code>static getDerivedStateFromProps(props, state)</code>：从 props 派生出 state（很少使用）。</li><li><code>render()</code>：产生 JSX。</li><li><code>componentDidMount()</code>：组件已挂载到真实 DOM，适合发起网络请求、添加订阅。</li></ol><p><strong>更新阶段</strong></p><ol><li><code>static getDerivedStateFromProps(props, state)</code>。</li><li><code>shouldComponentUpdate(nextProps, nextState)</code>：性能优化关键，决定是否重渲染，默认返回 true。</li><li><code>render()</code>。</li><li><code>getSnapshotBeforeUpdate(prevProps, prevState)</code>：获取更新前 DOM 信息，返回给 <code>componentDidUpdate</code>。</li><li><code>componentDidUpdate(prevProps, prevState, snapshot)</code>：更新后操作 DOM、请求数据。</li></ol><p><strong>卸载阶段</strong></p><ul><li><code>componentWillUnmount()</code>：清除定时器、取消订阅、防止内存泄漏。</li></ul><p><strong>错误处理</strong></p><ul><li><code>static getDerivedStateFromError(error)</code>：捕获子组件错误并更新 state 展示降级 UI。</li><li><code>componentDidCatch(error, info)</code>：记录错误日志。</li></ul>',10),d=[a];function s(i,n,l,p,_,m){return o(),t("div",null,d)}const g=e(c,[["render",s]]);export{h as __pageData,g as default};
